import { useStore } from '~/app/store/store';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { useCreateUserMutation } from '~/entities/pin/api/use-create-user-mutation';
import { useVerifyPinMutation } from '~/entities/pin/api/use-verify-pin-mutation';
import { useOnSubmit } from '~/entities/pin/lib/use-on-submit';
import { PinInterface } from '~/entities/pin/ui/pin-interface';
import { getUserRes, setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { PinInteractionMode, StepBeforeRegister } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

export const SetPinNumberPage = () => {
  const { callCreateUser, callAuthnRegister } = useOnSubmit();
  const { openAlertDialog } = useAlertDialog();
  const { navigate } = useNavigate();
  const { mutateAsync: createUser } = useCreateUserMutation({ throwOnError: false });
  const { mutateAsync: login } = useVerifyPinMutation({ throwOnError: false });

  const handleRegisterBusiness = (step: string) => {
    //사업자 등록 묻기
    openAlertDialog({
      message: i18n.t('validation:registerBusinessInformation'),
      buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
      onConfirmClick: () => {
        closeDialog(async () => {
          if (step === 'pin') {
            //확인 클릭 => 회원가입처리, 로그인 setting 후 사업자 등록 화면 이동하기
            const userRes = getUserRes() as UserResponse;
            useStore.getState().authSlice.setJwt(null);
            const response = await createUser(userRes);

            setUserRes((prev) => ({
              ...prev,
              tbCstmrMastr: {
                ...prev.tbCstmrMastr,
                cstmrNo: response.cstmrNo,
              },
              transkeyModel: userRes.transkeyModel,
              sid: response.sid,
            }));

            userRes.tbCstmrMastr = {
              ...userRes.tbCstmrMastr,
              cstmrNo: response.cstmrNo,
            };
            userRes.sid = response.sid;

            useStore.getState().authSlice.setJwt(null);
            await login(userRes);
            useStore.getState().superAppSlice.clearSuperAppData();
            notiBar(i18n.t('membershipComplete'));
          }
          navigate(PATHS.myWallet.business, { replace: true, state: { step: StepBeforeRegister.회원가입 } });
        });
      },
      onCancelClick: () => {
        //취소 클릭 => 사업자 등록 안함 => 이미 회원 등록된 상태이므로 home redirect
        closeDialog(() => {
          if (step === 'pin') {
            callCreateUser();
          } else {
            navigate(PATHS.home, { replace: true });
          }
        });
      },
    });
  };

  return (
    <PinInterface
      type={PinInteractionMode.신규입력}
      title={i18n.t('pin:titleSetPin')}
      message={i18n.t('pin:messageSetPin')}
      step={1}
      prevPin={''}
      pin={''}
      isError={false}
      handleCompleteInput={async () => {
        openAlertDialog({
          message: i18n.t('pin:messageSetBiometricConfirm'),
          buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
          onConfirmClick: () => {
            //생체인증 등록 시 => 회원등록 완료 후 사업자 등록 묻기
            closeDialog(() => {
              callAuthnRegister().then(() => {
                //로그인완료된상태, 생체등록시에는 해당로직 skip
                handleRegisterBusiness('auth');
              });
            });
          },
          onCancelClick: () => {
            //생체인증 등록안함 선택 시 => 사업자 등록 묻기
            closeDialog(() => {
              handleRegisterBusiness('pin');
            });
          },
        });
      }}
    />
  );
};
